// echo_selftest_top.sv -- opt-in on-chip packet generator + capture
// wrapper around echo_top.sv (generated by --self-test). See
// compiler/emit_selftest.py for the full design rationale and register map.
// axi_data_width=256 (MUST match the echo_top.sv this wraps)

module echo_selftest_top #(
    parameter int AXI_DATA_W     = 256,
    parameter int AXIL_ADDR_W    = 16,
    parameter int ST_AXIL_ADDR_W = 16
) (
    input  logic clk,
    input  logic rst_n,

    // Table control-plane AXI4-Lite -- passthrough to echo_top, unchanged
    input  logic [AXIL_ADDR_W-1:0]   s_axil_awaddr,
    input  logic                      s_axil_awvalid,
    output logic                      s_axil_awready,
    input  logic [31:0]               s_axil_wdata,
    input  logic [3:0]                s_axil_wstrb,
    input  logic                      s_axil_wvalid,
    output logic                      s_axil_wready,
    output logic [1:0]                s_axil_bresp,
    output logic                      s_axil_bvalid,
    input  logic                      s_axil_bready,
    input  logic [AXIL_ADDR_W-1:0]   s_axil_araddr,
    input  logic                      s_axil_arvalid,
    output logic                      s_axil_arready,
    output logic [31:0]               s_axil_rdata,
    output logic [1:0]                s_axil_rresp,
    output logic                      s_axil_rvalid,
    input  logic                      s_axil_rready,

    // Self-test AXI4-Lite -- generator/capture control (see register map above)
    input  logic [ST_AXIL_ADDR_W-1:0] st_axil_awaddr,
    input  logic                       st_axil_awvalid,
    output logic                       st_axil_awready,
    input  logic [31:0]                st_axil_wdata,
    input  logic [3:0]                 st_axil_wstrb,
    input  logic                       st_axil_wvalid,
    output logic                       st_axil_wready,
    output logic [1:0]                 st_axil_bresp,
    output logic                       st_axil_bvalid,
    input  logic                       st_axil_bready,
    input  logic [ST_AXIL_ADDR_W-1:0] st_axil_araddr,
    input  logic                       st_axil_arvalid,
    output logic                       st_axil_arready,
    output logic [31:0]                st_axil_rdata,
    output logic [1:0]                 st_axil_rresp,
    output logic                       st_axil_rvalid,
    input  logic                       st_axil_rready
);

  localparam int KEEP_W        = AXI_DATA_W / 8;  // 32
  localparam int MAX_PKT_BYTES = 256 * KEEP_W;  // 8192
  localparam int TMPL_BASE_WORD  = 16;
  localparam int CAP_BASE_WORD   = 2064;
  localparam int ADDR_SPAN_WORDS = 4112;

  // Template buffer (software-written packet content, read+write over
  // st_axil_*) and capture buffer (written only by the capture FSM below,
  // read over st_axil_*). Real BRAM cost -- see this file's module docstring.
  logic [7:0] tmpl_buf [0:MAX_PKT_BYTES-1];
  logic [7:0] cap_buf  [0:MAX_PKT_BYTES-1];
  `ifndef SYNTHESIS
  // synthesis translate_off
  initial begin
    for (int i = 0; i < MAX_PKT_BYTES; i++) tmpl_buf[i] = 8'd0;
    for (int i = 0; i < MAX_PKT_BYTES; i++) cap_buf[i]  = 8'd0;
  end
  // synthesis translate_on
  `endif

  logic [AXI_DATA_W-1:0] gen_axis_tdata;
  logic [KEEP_W-1:0]     gen_axis_tkeep;
  logic                   gen_axis_tvalid, gen_axis_tready, gen_axis_tlast;

  logic [AXI_DATA_W-1:0] cap_axis_tdata;
  logic [KEEP_W-1:0]     cap_axis_tkeep;
  logic                   cap_axis_tvalid, cap_axis_tlast;

  echo_top u_core (
    .clk(clk), .rst_n(rst_n),
    .s_axis_tdata(gen_axis_tdata), .s_axis_tkeep(gen_axis_tkeep),
    .s_axis_tvalid(gen_axis_tvalid), .s_axis_tready(gen_axis_tready), .s_axis_tlast(gen_axis_tlast),
    .m_axis_tdata(cap_axis_tdata), .m_axis_tkeep(cap_axis_tkeep),
    .m_axis_tvalid(cap_axis_tvalid), .m_axis_tready(1'b1), .m_axis_tlast(cap_axis_tlast),
    .s_axil_awaddr(s_axil_awaddr), .s_axil_awvalid(s_axil_awvalid), .s_axil_awready(s_axil_awready),
    .s_axil_wdata(s_axil_wdata), .s_axil_wstrb(s_axil_wstrb), .s_axil_wvalid(s_axil_wvalid), .s_axil_wready(s_axil_wready),
    .s_axil_bresp(s_axil_bresp), .s_axil_bvalid(s_axil_bvalid), .s_axil_bready(s_axil_bready),
    .s_axil_araddr(s_axil_araddr), .s_axil_arvalid(s_axil_arvalid), .s_axil_arready(s_axil_arready),
    .s_axil_rdata(s_axil_rdata), .s_axil_rresp(s_axil_rresp), .s_axil_rvalid(s_axil_rvalid), .s_axil_rready(s_axil_rready)
  );

  logic [13:0] gen_pkt_len_reg;
  logic [31:0] gen_pkt_count_reg;
  logic [12:0] gen_vary_offset_reg;
  logic gen_vary_enable_reg;
  logic [31:0] gen_ipg_reg;

  // ── Packet generator ─────────────────────────────────────────────────────
  typedef enum logic [1:0] {
    GEN_IDLE = 2'd0,
    GEN_SEND = 2'd1,
    GEN_GAP  = 2'd2
  } gen_st_t;
  gen_st_t gen_st;

  logic [13:0] pkt_len_r;
  logic [31:0] pkt_count_r;
  logic [12:0] vary_offset_r;
  logic vary_enable_r;
  logic [31:0] ipg_r;

  logic [31:0] pkt_idx, sent_count, ipg_cnt;
  logic [8:0]  beat_idx;  // holds 0..256 (MAX_PKT_BEATS)
  logic [7:0]  vary_val;
  logic        gen_busy, gen_done;

  logic [31:0] gen_nbeats_c;
  assign gen_nbeats_c = (pkt_len_r + KEEP_W - 1) / KEEP_W;
  assign gen_axis_tvalid = (gen_st == GEN_SEND);
  assign gen_axis_tlast  = (gen_st == GEN_SEND) && (beat_idx == gen_nbeats_c - 1);

  always @(*) begin
    for (int i = 0; i < KEEP_W; i = i + 1) begin
      if ((beat_idx * KEEP_W + i) < pkt_len_r) begin
        gen_axis_tkeep[i] = 1'b1;
        if (vary_enable_r && ((beat_idx * KEEP_W + i) == vary_offset_r))
          gen_axis_tdata[i*8 +: 8] = vary_val;
        else
          gen_axis_tdata[i*8 +: 8] = tmpl_buf[beat_idx * KEEP_W + i];
      end else begin
        gen_axis_tkeep[i] = 1'b0;
        gen_axis_tdata[i*8 +: 8] = 8'h00;
      end
    end
  end

  logic r_gen_start;  // one-cycle strobe, set by the self-test AXIL decoder below

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      gen_st      <= GEN_IDLE;
      gen_busy    <= 1'b0;
      gen_done    <= 1'b0;
      pkt_len_r     <= '0;
      pkt_count_r   <= 32'd0;
      vary_offset_r <= '0;
      vary_enable_r <= 1'b0;
      ipg_r         <= 32'd0;
      pkt_idx     <= 32'd0;
      sent_count  <= 32'd0;
      beat_idx    <= '0;
      vary_val    <= 8'd0;
      ipg_cnt     <= 32'd0;
    end else begin
      case (gen_st)
        GEN_IDLE: begin
          if (r_gen_start) begin
            pkt_len_r     <= (gen_pkt_len_reg > MAX_PKT_BYTES) ? 14'(MAX_PKT_BYTES) : gen_pkt_len_reg;
            pkt_count_r   <= gen_pkt_count_reg;
            vary_offset_r <= gen_vary_offset_reg;
            vary_enable_r <= gen_vary_enable_reg;
            ipg_r         <= gen_ipg_reg;
            vary_val      <= tmpl_buf[gen_vary_offset_reg];
            pkt_idx       <= 32'd0;
            beat_idx      <= '0;
            sent_count    <= 32'd0;
            gen_done      <= 1'b0;
            if (gen_pkt_count_reg == 32'd0 || gen_pkt_len_reg == '0) begin
              gen_busy <= 1'b0;
              gen_done <= 1'b1;
            end else begin
              gen_busy <= 1'b1;
              gen_st   <= GEN_SEND;
            end
          end
        end
        GEN_SEND: begin
          if (gen_axis_tvalid && gen_axis_tready) begin
            if (gen_axis_tlast) begin
              sent_count <= sent_count + 32'd1;
              pkt_idx    <= pkt_idx + 32'd1;
              beat_idx   <= '0;
              if (vary_enable_r) vary_val <= vary_val + 8'd1;
              if (pkt_idx + 32'd1 == pkt_count_r) begin
                gen_busy <= 1'b0;
                gen_done <= 1'b1;
                gen_st   <= GEN_IDLE;
              end else if (ipg_r == 32'd0) begin
                gen_st <= GEN_SEND;
              end else begin
                ipg_cnt <= ipg_r;
                gen_st  <= GEN_GAP;
              end
            end else begin
              beat_idx <= beat_idx + 9'd1;
            end
          end
        end
        GEN_GAP: begin
          if (ipg_cnt <= 32'd1) begin
            gen_st <= GEN_SEND;
          end else begin
            ipg_cnt <= ipg_cnt - 32'd1;
          end
        end
        default: gen_st <= GEN_IDLE;
      endcase
    end
  end

  // ── Packet capture ───────────────────────────────────────────────────────
  // m_axis_tready is tied high in u_core's instantiation above -- capture
  // never backpressures the DUT. A single cap_start arms recording for every
  // packet that arrives afterward, not just one: write_cursor resets to 0 at
  // the start of each new packet (right after the previous one's tlast), so
  // a multi-packet burst's LAST packet is what ends up in cap_buf/cap_byte_count
  // when the burst finishes -- captures only the most recent completed packet
  // (not every packet in a burst), bounding BRAM cost honestly. cap_done is a
  // sticky flag (set on the first completed packet, held through later ones),
  // not a terminal state -- recording never stops on its own, only a fresh
  // cap_start re-arms/resets it.
  typedef enum logic {
    CAP_IDLE  = 1'd0,
    CAP_ARMED = 1'd1
  } cap_st_t;
  cap_st_t cap_st;
  logic [31:0] write_cursor;   // resets to 0 at the start of each new packet
  logic [31:0] cap_byte_count; // length of the last COMPLETED packet (held stable)
  logic        cap_done;       // sticky: at least one packet captured since arm
  logic        cap_busy;
  assign cap_busy = (cap_st == CAP_ARMED);

  logic [7:0] cap_valid_bytes;  // popcount(cap_axis_tkeep) this beat
  always @(*) begin
    cap_valid_bytes = 8'd0;
    for (int i = 0; i < KEEP_W; i = i + 1)
      if (cap_axis_tkeep[i]) cap_valid_bytes = cap_valid_bytes + 8'd1;
  end

  logic r_cap_start;  // one-cycle strobe, set by the self-test AXIL decoder below

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      cap_st         <= CAP_IDLE;
      write_cursor   <= 32'd0;
      cap_byte_count <= 32'd0;
      cap_done       <= 1'b0;
    end else if (r_cap_start) begin
      cap_st         <= CAP_ARMED;
      write_cursor   <= 32'd0;
      cap_byte_count <= 32'd0;
      cap_done       <= 1'b0;
    end else if (cap_st == CAP_ARMED && cap_axis_tvalid) begin
      for (int i = 0; i < KEEP_W; i = i + 1) begin
        if (cap_axis_tkeep[i] && ((write_cursor + i) < MAX_PKT_BYTES))
          cap_buf[write_cursor + i] <= cap_axis_tdata[i*8 +: 8];
      end
      if (cap_axis_tlast) begin
        cap_byte_count <= write_cursor + {24'd0, cap_valid_bytes};
        write_cursor   <= 32'd0;  // ready for the next packet, if any
        cap_done       <= 1'b1;
      end else begin
        write_cursor <= write_cursor + {24'd0, cap_valid_bytes};
      end
    end
  end

  // ── Self-test AXI4-Lite decoder (own bus, own FSM -- see register map above) ──
  // (staging-register declarations for gen_pkt_len_reg/etc. are hoisted to
  // before _write_generator -- see the call site in _write_module.)

  typedef enum logic [1:0] {
    ST_AXIL_IDLE  = 2'd0,
    ST_AXIL_WDATA = 2'd1,
    ST_AXIL_BRESP = 2'd2
  } st_axil_st_t;
  st_axil_st_t st_axil_st;
  logic [ST_AXIL_ADDR_W-1:0] st_axil_awaddr_r;

  assign st_axil_awready = (st_axil_st == ST_AXIL_IDLE);
  assign st_axil_bvalid  = (st_axil_st == ST_AXIL_BRESP);
  assign st_axil_bresp   = 2'b00;
  assign st_axil_wready  = (st_axil_st == ST_AXIL_WDATA);

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      st_axil_st <= ST_AXIL_IDLE;
      r_gen_start <= 1'b0;
      r_cap_start <= 1'b0;
      gen_pkt_len_reg     <= '0;
      gen_pkt_count_reg   <= 32'd0;
      gen_vary_offset_reg <= '0;
      gen_vary_enable_reg <= 1'b0;
      gen_ipg_reg         <= 32'd0;
    end else begin
      r_gen_start <= 1'b0;
      r_cap_start <= 1'b0;
      case (st_axil_st)
        ST_AXIL_IDLE: begin
          if (st_axil_awvalid) begin
            st_axil_awaddr_r <= st_axil_awaddr;
            st_axil_st       <= ST_AXIL_WDATA;
          end
        end
        ST_AXIL_WDATA: begin
          if (st_axil_wvalid && st_axil_wready) begin
            if (st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] < 14'd16) begin
              case (st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2])
                14'd0: gen_pkt_len_reg     <= st_axil_wdata[13:0];
                14'd1: gen_pkt_count_reg   <= st_axil_wdata;
                14'd2: gen_vary_offset_reg <= st_axil_wdata[12:0];
                14'd3: gen_vary_enable_reg <= st_axil_wdata[0];
                14'd4: gen_ipg_reg         <= st_axil_wdata;
                14'd5: r_gen_start         <= 1'b1;
                14'd8: r_cap_start         <= 1'b1;
                default: ; // 6,7,9,10,11 read-only; 12-15 reserved
              endcase
            end else if (st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] < 14'd2064) begin
              // template buffer word write -- big-endian byte packing (see register map)
              tmpl_buf[(st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+0] <= st_axil_wdata[31:24];
              tmpl_buf[(st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+1] <= st_axil_wdata[23:16];
              tmpl_buf[(st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+2] <= st_axil_wdata[15:8];
              tmpl_buf[(st_axil_awaddr_r[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+3] <= st_axil_wdata[7:0];
            end
            // cap_buf region (and beyond): write ignored, still BRESP'd below
            st_axil_st <= ST_AXIL_BRESP;
          end
        end
        ST_AXIL_BRESP: begin
          if (st_axil_bready) st_axil_st <= ST_AXIL_IDLE;
        end
        default: st_axil_st <= ST_AXIL_IDLE;
      endcase
    end
  end

  // AXI4-Lite read channel. Note the DELIBERATE choice to sample st_r_rdata
  // via a real registered case (below), and to expose it through st_axil_rdata
  // for exactly one cycle while st_axil_rst==ST_AXIL_R_DATA -- a testbench must
  // sample it UNDELAYED at that same edge, not one edge later, since
  // st_axil_rready is expected to be tied high by most drivers (see this
  // project's own tb_fiveTuple_top.sv axil_read task and its comments for the
  // exact race this caught previously).
  typedef enum logic {
    ST_AXIL_R_IDLE = 1'd0,
    ST_AXIL_R_DATA = 1'd1
  } st_axil_rst_t;
  st_axil_rst_t st_axil_rst;
  logic [31:0] st_r_rdata;

  assign st_axil_arready = (st_axil_rst == ST_AXIL_R_IDLE);
  assign st_axil_rdata   = st_r_rdata;
  assign st_axil_rresp   = 2'b00;
  assign st_axil_rvalid  = (st_axil_rst == ST_AXIL_R_DATA);

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      st_axil_rst <= ST_AXIL_R_IDLE;
    end else begin
      case (st_axil_rst)
        ST_AXIL_R_IDLE: begin
          if (st_axil_arvalid) begin
            if (st_axil_araddr[ST_AXIL_ADDR_W-1:2] < 14'd16) begin
              case (st_axil_araddr[ST_AXIL_ADDR_W-1:2])
                14'd6:  st_r_rdata <= {30'd0, gen_done, gen_busy};
                14'd7:  st_r_rdata <= sent_count;
                14'd9:  st_r_rdata <= {30'd0, cap_done, cap_busy};
                14'd10: st_r_rdata <= cap_byte_count;
                14'd11: st_r_rdata <= 32'd8192;
                default: st_r_rdata <= 32'd0;
              endcase
            end else if (st_axil_araddr[ST_AXIL_ADDR_W-1:2] < 14'd2064) begin
              st_r_rdata <= {tmpl_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+0],
                             tmpl_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+1],
                             tmpl_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+2],
                             tmpl_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd16)*4+3]};
            end else if (st_axil_araddr[ST_AXIL_ADDR_W-1:2] < 14'd4112) begin
              st_r_rdata <= {cap_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd2064)*4+0],
                             cap_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd2064)*4+1],
                             cap_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd2064)*4+2],
                             cap_buf[(st_axil_araddr[ST_AXIL_ADDR_W-1:2] - 14'd2064)*4+3]};
            end else begin
              st_r_rdata <= 32'd0;
            end
            st_axil_rst <= ST_AXIL_R_DATA;
          end
        end
        ST_AXIL_R_DATA: begin
          if (st_axil_rready) st_axil_rst <= ST_AXIL_R_IDLE;
        end
        default: st_axil_rst <= ST_AXIL_R_IDLE;
      endcase
    end
  end

endmodule
